use crate::wasi::clocks::wall_clock;

struct Node;

/// Convert days since 1970-01-01 to (year, month, day) in the proleptic
/// Gregorian calendar (Howard Hinnant's civil_from_days algorithm).
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        let _ = tick;

        let now = wall_clock::now();
        let days = (now.seconds / 86_400) as i64;
        let (y, m, d) = civil_from_days(days);

        // Clamp the year so the formatted date is always exactly 10 characters.
        let y = y.clamp(0, 9_999);

        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started: now.seconds,
        }
    }
}

export!(Node);
```

